CREATE TEMP TABLE imported_fastcups ON COMMIT DROP AS
SELECT * FROM jsonb_to_recordset($tournaments$
[{"slug":"ls-fastcup-3","name":"LS Fastcup #3","description":"8 команд, плей-офф с выбыванием после двух поражений по результатам сетки турнира.","about":"Captain's Draft. Сумма ММР пяти игроков — не более 19000, минимальный ранг — Герой.","startAt":"2024-05-24T22:00:00+03:00","endAt":"2024-05-26T23:59:00+03:00","registrationDeadline":"2024-05-24T22:00:00+03:00","maxTeams":8,"groupFormat":"Без группового этапа","playoffFormat":"Double Elimination · 8 команд","finalFormat":"Гранд-финал · BO3","advanceToPlayoff":0,"gameMode":"Captain's Draft","playoffType":"double_elimination"},{"slug":"ls-fastcup-4","name":"LS Fastcup #4","description":"8 команд, плей-офф с выбыванием после двух поражений по результатам сетки турнира.","about":"Captain's Draft. Сумма ММР пяти игроков — не более 21500, минимальный ранг — Герой.","startAt":"2024-06-28T22:00:00+03:00","endAt":"2024-06-30T23:59:00+03:00","registrationDeadline":"2024-06-28T22:00:00+03:00","maxTeams":8,"groupFormat":"Без группового этапа","playoffFormat":"Double Elimination · 8 команд","finalFormat":"Гранд-финал · BO3","advanceToPlayoff":0,"gameMode":"Captain's Draft","playoffType":"double_elimination"},{"slug":"ls-fastcup-5","name":"LS Fastcup #5","description":"6 команд, групповой этап и плей-офф по результатам таблицы турнира.","about":"Captain's Mode. Сумма ММР пяти игроков — не более 21500, минимальный ранг — Герой.","startAt":"2024-07-26T22:00:00+03:00","endAt":"2024-08-04T23:59:00+03:00","registrationDeadline":"2024-07-26T22:00:00+03:00","maxTeams":6,"groupFormat":"2 группы · по 3 команды · BO2","playoffFormat":"Полуфиналы и матч за 3-е место · 4 команды · BO3","finalFormat":"Гранд-финал · BO3","advanceToPlayoff":2,"gameMode":"Captain's Mode","playoffType":"single_elimination"}]
$tournaments$::jsonb) AS source(
  slug TEXT, name TEXT, description TEXT, about TEXT,
  "startAt" TIMESTAMPTZ, "endAt" TIMESTAMPTZ,
  "registrationDeadline" TIMESTAMPTZ, "maxTeams" SMALLINT,
  "groupFormat" TEXT, "playoffFormat" TEXT, "finalFormat" TEXT,
  "advanceToPlayoff" SMALLINT, "gameMode" TEXT, "playoffType" TEXT
);

INSERT INTO tournaments (
  slug, name, eyebrow, headline, headline_accent, description, about,
  start_at, end_at, registration_deadline, status_label, format,
  team_size, max_teams, region, server, check_in_minutes,
  group_format, playoff_format, final_format, discord_url, status,
  playoff_type
)
SELECT
  source.slug, source.name, 'Архивный турнир', source.name,
  TO_CHAR(source."startAt" AT TIME ZONE 'Europe/Moscow', 'DD.MM.YYYY')
    || ' — ' || TO_CHAR(source."endAt" AT TIME ZONE 'Europe/Moscow', 'DD.MM.YYYY'),
  source.description, source.about, source."startAt", source."endAt",
  source."registrationDeadline", 'Турнир завершён',
  source."gameMode" || ' · 5 × 5', 5, source."maxTeams", '', 'Stockholm', 60,
  source."groupFormat", source."playoffFormat", source."finalFormat",
  'https://discord.gg/lsesports', 'archived', source."playoffType"
FROM imported_fastcups source
ON CONFLICT (slug) DO NOTHING;

