$matches$::jsonb) AS source(
  slug TEXT, "matchKey" TEXT, "scheduledAt" TIMESTAMPTZ, stage TEXT,
  "groupName" TEXT, "teamA" TEXT, "teamB" TEXT,
  "scoreA" SMALLINT, "scoreB" SMALLINT, "bestOf" SMALLINT,
  "resultType" TEXT, "labelA" TEXT, "labelB" TEXT, "decisionNote" TEXT,
  "bracketRound" SMALLINT, "bracketSide" TEXT, "bracketSlot" SMALLINT,
  "winnerToKey" TEXT, "winnerToSlot" CHAR(1),
  "loserToKey" TEXT, "loserToSlot" CHAR(1),
  "eliminatedTeam" TEXT, "sortOrder" SMALLINT, "isFinal" BOOLEAN
);

INSERT INTO tournament_matches (
  tournament_id, group_id, scheduled_at, stage,
  team_a_application_id, team_b_application_id,
  team_a_score, team_b_score, best_of, status, sort_order,
  result_type, team_a_result_label, team_b_result_label, decision_note,
  bracket_round, bracket_side, bracket_slot,
  eliminated_team_application_id
)
SELECT
  tournament.id, tournament_group.id, source."scheduledAt", source.stage,
  team_a.id, team_b.id, source."scoreA", source."scoreB", source."bestOf",
  'finished', source."sortOrder", source."resultType", source."labelA",
  source."labelB", source."decisionNote", source."bracketRound",
  source."bracketSide", source."bracketSlot", eliminated_team.id
FROM imported_fastcup_matches source
JOIN tournaments tournament ON tournament.slug = source.slug
JOIN tournament_team_applications team_a
  ON team_a.tournament_id = tournament.id AND team_a.team_name = source."teamA"
JOIN tournament_team_applications team_b
  ON team_b.tournament_id = tournament.id AND team_b.team_name = source."teamB"
LEFT JOIN tournament_groups tournament_group
  ON tournament_group.tournament_id = tournament.id
 AND tournament_group.name = source."groupName"
LEFT JOIN tournament_team_applications eliminated_team
  ON eliminated_team.tournament_id = tournament.id
 AND eliminated_team.team_name = source."eliminatedTeam"
WHERE NOT EXISTS (
  SELECT 1 FROM tournament_matches existing
  WHERE existing.tournament_id = tournament.id
    AND existing.sort_order = source."sortOrder"
);

UPDATE tournament_matches source_match
SET winner_to_match_id = winner_match.id,
    winner_to_slot = source."winnerToSlot",
    loser_to_match_id = loser_match.id,
    loser_to_slot = source."loserToSlot"
FROM imported_fastcup_matches source
JOIN tournaments tournament ON tournament.slug = source.slug
LEFT JOIN imported_fastcup_matches winner_source
  ON winner_source.slug = source.slug AND winner_source."matchKey" = source."winnerToKey"
LEFT JOIN tournament_matches winner_match
  ON winner_match.tournament_id = tournament.id
 AND winner_match.sort_order = winner_source."sortOrder"
LEFT JOIN imported_fastcup_matches loser_source
  ON loser_source.slug = source.slug AND loser_source."matchKey" = source."loserToKey"
LEFT JOIN tournament_matches loser_match
  ON loser_match.tournament_id = tournament.id
 AND loser_match.sort_order = loser_source."sortOrder"
WHERE source_match.tournament_id = tournament.id
  AND source_match.sort_order = source."sortOrder";

CREATE TEMP TABLE imported_fastcup_rules ON COMMIT DROP AS
SELECT * FROM jsonb_to_recordset($rules$
[{"slug":"ls-fastcup-3","sortOrder":1,"ruleText":"Регистрация на турнир проходит через форму (https://forms.gle/8xnb2LuYw571KTwA8)"},{"slug":"ls-fastcup-3","sortOrder":2,"ruleText":"Игроки 0169 и Immersion имеют фиксированный рейтинг для турнира. 0169 - 3850 ММР, Immersion - 2310 ММР. Остальные игроки, имеющие завышение или занижение тира во время серверных ивентов не имеют фиксированного рейтинга на фасткапе и регистрируются по текущему ММР."},{"slug":"ls-fastcup-3","sortOrder":3,"ruleText":"Показатель ММР каждого игрока будет рассматриваться индивидуально. Показатель ММР игрока для турнира может быть вручную отредактирован организатором на его усмотрение. Участники могут быть так же отстранены от участия на усмотрение организатора. Подлог аккаунтов, скриншотов с ММР и ММР игроков приводят к снятию всей команды нарушителя и постоянному бану на сервере для нарушевшего. Умышленная потеря ММР для турнира (умышленность потери определяется на усмотрение организатора) может привести к предупреждению с прибавлением ММР по количеству проигранных игр, повторное нарушение - отстранение от турнира."},{"slug":"ls-fastcup-3","sortOrder":4,"ruleText":"Регистрировать на турнир в составах команд можно только игроков, заигранных ранее на турнирах Linken's Sphere. Исключение - один слот в команде может занять \"легионер\" - игрок, не заигранный на сервере, допуск таких игроков на усмотрение организатора, перед регистрацией таких игроков кандидатуру нужно одобрить у организатора, предоставив всю доступную информацию по аккаунту игрока. В качестве исключения при недоборе игроков в последние дни регистрации и недоборе 8 команд, разрешено зарегистрировать еще одного легионера, но добавление еще одного игрока незаигранного на сервере так же нужно согласовать."},{"slug":"ls-fastcup-3","sortOrder":5,"ruleText":"На турнире предусмотрено 8 слотов для команд, 2 приглашенные с фиксированным слотом и 6 команд из регистрации. Если команд будет более 8, 9 и последующие команды, отправившие регистрационную форму, не попадут на турнир."},{"slug":"ls-fastcup-3","sortOrder":6,"ruleText":"Матч проводится на сервере Стокгольм с задержкой для зрителей 2 минуты (без турнира)."},{"slug":"ls-fastcup-3","sortOrder":7,"ruleText":"Правила выбора стороны и очередности пика аналогичны другим ивентам. В бо1 матчах монетка, в бо3 сериях на первой и третьей картах монетка, на второй первой выбирает сторону или очередность пика команда, проигравшая бросок монетки на первой карте."},{"slug":"ls-fastcup-3","sortOrder":8,"ruleText":"Дата и время старта матчей указаны на листе \"турнир\". Опоздание команды более чем на 30 минут на игру приведет к её дисквалификации. Опоздание до 15 минут без штрафа. Опоздание от 15 до 30 минут - оппонент выбирает вам героя на последний пик из 3-х предложенных вами оппоненту."},{"slug":"ls-fastcup-3","sortOrder":9,"ruleText":"Пауза на карту - не более 10 минут на команду в бо1 матчах и не более 20 на команду в серии в бо3 матчах"},{"slug":"ls-fastcup-3","sortOrder":10,"ruleText":"Для участия в матче игроки устанавливают в Steam и в \"изменить проф. информацию и команды\" в настройках в клиенте игры свой серверный ник, если его нет - нужно пройти регистрацию на сервере."},{"slug":"ls-fastcup-3","sortOrder":11,"ruleText":"Каждая команда обязана создать себе команду в клиенте игры."},{"slug":"ls-fastcup-3","sortOrder":12,"ruleText":"В ходе турнира, использовать чат в матчах могут только капитаны команд и только для обсуждения организационных вопросов и обозначения причины паузы. \"gwr\", \"gg\", \"glhf\" в определенных случаях (при готовности после паузы, сдаче, в начале карты соответственно) разрешены всем игрокам."},{"slug":"ls-fastcup-3","sortOrder":13,"ruleText":"Одобренные зарегистрированные команды появятся в разделе Составы."},{"slug":"ls-fastcup-3","sortOrder":14,"ruleText":"Правила могут дополняться как до, так и в ходе турнира."},{"slug":"ls-fastcup-3","sortOrder":15,"ruleText":"(22.05) Игроки Yoma, yyukimaru, Kuporu не могут принять участие в текущем фасткапе"},{"slug":"ls-fastcup-3","sortOrder":16,"ruleText":"(25.05) Игрок iFlopz! отстранен от участия в серверных ивентах межьсезонья, за исключением лиги межьсезонья"},{"slug":"ls-fastcup-4","sortOrder":1,"ruleText":"Регистрация на турнир проходит через форму (https://forms.gle/8xnb2LuYw571KTwA8)"},{"slug":"ls-fastcup-4","sortOrder":2,"ruleText":"Рейтинг участников зафиксирован в разделе \"Отметка ММР-показателя\""},{"slug":"ls-fastcup-4","sortOrder":3,"ruleText":"Показатель ММР каждого игрока будет рассматриваться индивидуально. Показатель ММР игрока для турнира может быть вручную отредактирован организатором на его усмотрение. Участники могут быть так же отстранены от участия на усмотрение организатора. Подлог аккаунтов, скриншотов с ММР и ММР игроков приводят к снятию всей команды нарушителя и постоянному бану на сервере для нарушевшего. Умышленная потеря ММР для турнира (умышленность потери определяется на усмотрение организатора) может привести к предупреждению с прибавлением ММР по количеству проигранных игр, повторное нарушение - отстранение от турнира."},{"slug":"ls-fastcup-4","sortOrder":4,"ruleText":"Регистрировать на турнир в составах команд можно только игроков, заигранных ранее на турнирах Linken's Sphere. Исключение - один слот в команде может занять \"легионер\" - игрок, не заигранный на серверных сехонных ивентах, допуск таких игроков на усмотрение организатора, перед регистрацией таких игроков кандидатуру нужно одобрить у организатора, предоставив всю доступную информацию по аккаунту игрока. В качестве исключения при недоборе игроков в последние дни регистрации и недоборе 8 команд, разрешено зарегистрировать еще одного легионера, но добавление еще одного игрока незаигранного на сервере так же нужно согласовать."},{"slug":"ls-fastcup-4","sortOrder":5,"ruleText":"Команде разрешено сделать замену, но не более одной. Возможны исключения, при которых замены сверх одной сделанной предоставляются организатором. Замена должна быть согласована и ММР замены не должен превышать ММР заменяемого игрока."},{"slug":"ls-fastcup-4","sortOrder":6,"ruleText":"На турнире предусмотрено 8 слотов для команд. Если команд будет более 8, 9 и последующие команды, отправившие регистрационную форму, не попадут на турнир."},{"slug":"ls-fastcup-4","sortOrder":7,"ruleText":"Матч проводится на сервере Стокгольм с задержкой для зрителей 5 минуты (с билетом). Капитаны команд обязаны получить билет у организатора до старта турнира."},{"slug":"ls-fastcup-4","sortOrder":8,"ruleText":"Правила выбора стороны и очередности пика аналогичны другим ивентам. В бо1 матчах монетка, в бо3 сериях на первой и третьей картах монетка, на второй первой выбирает сторону или очередность пика команда, проигравшая бросок монетки на первой карте."},{"slug":"ls-fastcup-4","sortOrder":9,"ruleText":"Дата и время старта матчей указаны на листе \"турнир\". Опоздание команды более чем на 30 минут на игру приведет к её дисквалификации. Опоздание до 15 минут без штрафа. Опоздание от 15 до 30 минут - оппонент выбирает вам героя на последний пик из 3-х предложенных вами оппоненту."},{"slug":"ls-fastcup-4","sortOrder":10,"ruleText":"Пауза на карту - не более 15 минут на команду в бо1 матчах и не более 25 на команду в серии в бо3 матчах."},{"slug":"ls-fastcup-4","sortOrder":11,"ruleText":"Для участия в матче игроки устанавливают в Steam и в \"изменить проф. информацию и команды\" в настройках в клиенте игры свой серверный ник, если его нет - нужно пройти регистрацию на сервере."},{"slug":"ls-fastcup-4","sortOrder":12,"ruleText":"Каждая команда обязана создать себе команду в клиенте игры."},{"slug":"ls-fastcup-4","sortOrder":13,"ruleText":"Одобренные зарегистрированные команды появятся в разделе Составы."},{"slug":"ls-fastcup-4","sortOrder":14,"ruleText":"Правила могут дополняться как до, так и в ходе турнира."},{"slug":"ls-fastcup-4","sortOrder":15,"ruleText":"Снятие с турнира после регистрации по неуважительной причине приведет к потере 2 очков DPC"},{"slug":"ls-fastcup-5","sortOrder":1,"ruleText":"Регистрация на турнир проходит через форму (https://forms.gle/ZGKBLZFD14VzXjMMA)"},{"slug":"ls-fastcup-5","sortOrder":2,"ruleText":"Рейтинг участников зафиксирован в разделе \"Отметка ММР-показателя\""},{"slug":"ls-fastcup-5","sortOrder":3,"ruleText":"Показатель ММР каждого игрока будет рассматриваться индивидуально. Показатель ММР игрока для турнира может быть вручную отредактирован организатором на его усмотрение. Участники могут быть так же отстранены от участия на усмотрение организатора. Подлог аккаунтов, скриншотов с ММР и ММР игроков приводят к снятию всей команды нарушителя и постоянному бану на сервере для нарушевшего. Умышленная потеря ММР для турнира (умышленность потери определяется на усмотрение организатора) может привести к предупреждению с прибавлением ММР по количеству проигранных игр, повторное нарушение - отстранение от турнира."},{"slug":"ls-fastcup-5","sortOrder":4,"ruleText":"Регистрировать на турнир в составах команд можно только игроков, заигранных ранее на турнирах Linken's Sphere. Исключение - один слот в команде может занять \"легионер\" - игрок, не заигранный на серверных сезонных ивентах или лигах межсезонья, допуск таких игроков на усмотрение организатора, перед регистрацией таких игроков кандидатуру нужно одобрить у организатора, предоставив всю доступную информацию по аккаунту игрока. В качестве исключения при недоборе игроков в последние дни регистрации и недоборе 8 команд, разрешено зарегистрировать еще одного легионера, но добавление еще одного игрока незаигранного на сервере так же нужно согласовать."},{"slug":"ls-fastcup-5","sortOrder":5,"ruleText":"На момент турнира, у игроков должен быть открытый профиль на stratz или dotabuff"},{"slug":"ls-fastcup-5","sortOrder":6,"ruleText":"Команде разрешено сделать замену после регистрации, но не более одной. Возможны исключения, при которых замены сверх одной сделанной предоставляются организатором. Замена должна быть согласована и ММР замены не должен превышать ММР заменяемого игрока."},{"slug":"ls-fastcup-5","sortOrder":7,"ruleText":"На турнире предусмотрено 8 слотов для команд. Команды зарегистрированные сверх 8 команд на турнир не попадают, приоритет отдается более ранним регистрациям."},{"slug":"ls-fastcup-5","sortOrder":8,"ruleText":"Матч проводится на сервере Стокгольм с задержкой для зрителей 5 минуты (с билетом). Капитаны команд обязаны получить билет у организатора до старта турнира."},{"slug":"ls-fastcup-5","sortOrder":9,"ruleText":"Правила выбора стороны и очередности пика аналогичны другим ивентам. В бо1 матчах монетка, в бо3 сериях на первой и третьей картах монетка, на второй первой выбирает сторону или очередность пика команда, проигравшая бросок монетки на первой карте."},{"slug":"ls-fastcup-5","sortOrder":10,"ruleText":"Дата и время старта матчей указаны на листе \"турнир\". Опоздание команды более чем на 30 минут на игру приведет к её техническому поражению во встрече. Опоздание до 15 минут без штрафа. Опоздание от 15 до 30 минут - оппонент имеет возможность сделать еще три бана устно, обозначив их оппоненту через чат, которые должны учитываться при драфте, как баны сделанные капитаном оппонента в игре."},{"slug":"ls-fastcup-5","sortOrder":11,"ruleText":"Пауза на карту - не более 15 минут на команду в бо1 матчах и не более 25 на команду в серии в бо3 матчах."},{"slug":"ls-fastcup-5","sortOrder":12,"ruleText":"Для участия в матче игроки устанавливают в Steam и в \"изменить проф. информацию и команды\" в настройках в клиенте игры свой серверный ник, если его нет - нужно пройти регистрацию на сервере."},{"slug":"ls-fastcup-5","sortOrder":13,"ruleText":"Каждая команда обязана создать себе команду в клиенте игры."},{"slug":"ls-fastcup-5","sortOrder":14,"ruleText":"Одобренные зарегистрированные команды появятся в разделе Составы."},{"slug":"ls-fastcup-5","sortOrder":15,"ruleText":"Правила могут дополняться как до, так и в ходе турнира."},{"slug":"ls-fastcup-5","sortOrder":16,"ruleText":"Снятие с турнира после регистрации по неуважительной причине приведет к потере 2 очков DPC."}]
$rules$::jsonb) AS source(
  slug TEXT, "sortOrder" SMALLINT, "ruleText" TEXT
);

INSERT INTO tournament_rules (tournament_id, sort_order, rule_text)
SELECT tournament.id, source."sortOrder", source."ruleText"
FROM imported_fastcup_rules source
JOIN tournaments tournament ON tournament.slug = source.slug
ON CONFLICT (tournament_id, sort_order) DO NOTHING;

INSERT INTO tournament_team_results (application_id, placement, result_label)
SELECT application.id, source.placement, source."resultLabel"
FROM imported_fastcup_teams source
JOIN tournaments tournament ON tournament.slug = source.slug
JOIN tournament_team_applications application
  ON application.tournament_id = tournament.id
 AND application.team_name = source."teamName"
ON CONFLICT (application_id) DO NOTHING;

INSERT INTO tournament_prizes (
  tournament_id, placement, application_id, team_name_snapshot, prize_text
)
SELECT tournament.id, source.placement, application.id,
  source."teamName", source."prizeText"
FROM imported_fastcup_teams source
JOIN tournaments tournament ON tournament.slug = source.slug
JOIN tournament_team_applications application
  ON application.tournament_id = tournament.id
 AND application.team_name = source."teamName"
WHERE source.placement IS NOT NULL
ON CONFLICT (tournament_id, placement) DO NOTHING;

CREATE TEMP TABLE imported_fastcup_schedule ON COMMIT DROP AS
